import React, { Fragment, useState } from "react";
import {
  Col,
  Form,
  FormGroup,
  Label,
  Input,
  FormText,
  CustomInput
} from "reactstrap";
import { Button } from "@material-ui/core";
import axios from "axios";
import Message from "./Message";
import ProgressBar from "./ProgressBar";
export default function FileUpload() {
  //State
  const [file, setFile] = useState("");
  const [fileName, setFileName] = useState("");
  const [uploadedFile, setUploadedFile] = useState({});
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState();
  const [uploadPercentage, setUploadPercentage] = useState();
  const [parsedStepFile, setParsedStepFile] = useState({});
  const [stepFileElementCount, setStepFileElementCount] = useState({});
  //Methods
  const onChange = e => {
    //e.preventDefault();
    setFile(e.target.files[0]);
    setFileName(e.target.files[0].name);
  }; /*
        onUploadProgress: progressEvent => {
          setUploadPercentage(
            parseInt(
              Math.round((progressEvent.loaded * 100) / progressEvent.total)
            )
          );
          setTimeout(() => setUploadPercentage(0), 1000);
        }
      });
      const { fileName, filePath } = res.data;
      setUploadedFile({ fileName, filePath });
      setMessageType(1);
      setMessage("File Uploaded");
    } catch (err) {
      if (err.response.status === 500) {
        setMessageType(2);
        setMessage("There was a problem with the server");
      } else {
        setMessage(err.response.data.msg);
        setMessageType(2);
      }
    }
  };*/
  /*const onSubmit = async e => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("file", file);
    try {
      const res = await axios.post("/api/upload", formData, {
        /* headers: {
          "Content-Type": "multipart/form-data"
        },*/

  const onSubmit = e => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("file", file);
    axios
      .post("/api/upload", formData)
      .then(res => {
        console.log(res.data);
      })
      .catch(err => {
        console.log(err);
      });
  };
  const getFiles = () => {
    axios
      .get(`/api/upload`)
      .then(res => {
        console.log(res.data);
      })
      .catch(err => {
        console.log(err);
      });
  };
  const getOneFile = () => {
    axios
      .get(`/api/upload/${"5ec74bfa312ab08288522a01"}`)
      .then(res => {
        parseStepFile(res.data);
      })
      .catch(err => {
        console.log(err);
      });
  };
  const parseStepFile = fS => {
    var parsingFile = fS.slice(fS.indexOf("DATA;") + 6, fS.length);
    //console.log(parsingFile);
    var i = 0;
    var exitVar = 0;
    var stepElementObject = {};
    var elementDetails;
    var elementName;
    var elementDetail;

    while (exitVar !== -1) {
      i++;
      var numIndexCurrent = parsingFile.indexOf(`#${i} =`);
      var numIndexNext = parsingFile.indexOf(`#${i + 1} =`);
      if (numIndexNext === -1) {
        numIndexNext = parsingFile.indexOf(`ENDSEC;`);
        exitVar = -1;
      }
      var parsedElement = parsingFile.slice(numIndexCurrent, numIndexNext);
      elementDetails = parseStepFileElement(parsedElement);
      elementName = elementDetails[0];
      elementDetail = elementDetails[1];

      stepElementObject[i] = {
        rawElement: parsedElement,
        elementName: elementName,
        elementDetail: elementDetail
      };
    }
    setStepFileElementCount(i);
    setParsedStepFile(stepElementObject);
    parseClosedShell();
    //console.log(stepElementObject);
    //console.log(i);
  };
  const parseStepFileElement = element => {
    //find space = space.  if not found use space =
    var transitionElement;
    var parsedElementName;
    var parsedElementDetail;
    var start = element.indexOf(` = `);
    if (start !== -1) {
      transitionElement = element.slice(start + 3, element.length);
      parsedElementName = transitionElement.slice(
        0,
        transitionElement.indexOf(" ")
      );
      parsedElementDetail = transitionElement.slice(
        transitionElement.indexOf(" ") + 1,
        element.length
      );
    } else {
      start = element.indexOf(` =`);
      parsedElementName = element.slice(start + 2, element.length);
      parsedElementDetail = "";
    }
    return [parsedElementName, parsedElementDetail];
  };

  const parseClosedShell = () => {
    var closedShellElement = "";
    for (var i = 1; i < stepFileElementCount; i++) {
      if (parsedStepFile[i].elementName === "CLOSED_SHELL") {
        closedShellElement = parsedStepFile[i];
        console.log(parsedStepFile[i]);
        console.log(parsedStepFile[i].elementDetail.indexOf("(", 1));
        console.log(
          parsedStepFile[i].slice(
            parsedStepFile[i].elementDetail.indexOf("(", 1),
            parsedStepFile[i].elementDetail.indexOf(")")
          )
        );
      }
    }
  };
  return (
    <Fragment>
      {message ? <Message msg={message} type={messageType} /> : null}
      {uploadPercentage > 0 && uploadPercentage <= 100 ? (
        <ProgressBar percentage={uploadPercentage} />
      ) : null}

      <Form onSubmit={onSubmit} encType="multipart/form-data">
        <FormGroup row>
          <Button
            style={{ marginLeft: "1%" }}
            variant="contained"
            color="primary"
            type="submit"
            value="upload"
          >
            Load File
          </Button>

          <Col>
            <CustomInput
              type="file"
              id="file"
              name="file"
              label="Upload Goal Geometry File - STEP Files Only"
              onChange={onChange}
            />
          </Col>
        </FormGroup>
      </Form>
      <Button style={{ marginLeft: "1%" }} color="primary" onClick={getFiles}>
        Get All File Descriptions
      </Button>
      <Button style={{ marginLeft: "1%" }} color="primary" onClick={getOneFile}>
        Get 1 File Desc and Contents
      </Button>
    </Fragment>
  );
}
